var MM_BEZ_DVIZHENIE = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
function setMenu(open) {
var mm = document.getElementById('mobile-menu');
if (!mm) return;
var nav = document.getElementById('main-nav');
var h = document.getElementById('hamburger');
clearTimeout(mm._zatvaryane);
if (open) {
mm.classList.remove('closing');
if (nav) mm.style.top = Math.max(0, Math.round(nav.getBoundingClientRect().bottom)) + 'px';
mm.classList.add('open');
} else if (mm.classList.contains('open')) {
if (MM_BEZ_DVIZHENIE) mm.classList.remove('open', 'closing');
else {
mm.classList.add('closing');
mm._zatvaryane = setTimeout(function () { mm.classList.remove('open', 'closing'); }, 180);
}
}
document.documentElement.classList.toggle('menu-open', open);
if (h) h.setAttribute('aria-expanded', open ? 'true' : 'false');
}
function toggleMenu() {
var mm = document.getElementById('mobile-menu');
if (mm) setMenu(!mm.classList.contains('open') || mm.classList.contains('closing'));
}
var NA_ANGLIYSKI = location.pathname.indexOf('/en/') === 0 || location.pathname === '/en';
(function () {
var vrazki = document.querySelectorAll('a[data-lang-alt]');
if (!vrazki.length) return;
[].forEach.call(vrazki, function (a) {
var ez = a.getAttribute('hreflang');
var l = document.querySelector('link[rel="alternate"][hreflang="' + ez + '"]');
if (l && l.href) a.href = l.href;
});
})();
(function () {
var path = location.pathname;
var links = document.querySelectorAll('.nav-links > li > a');
[].forEach.call(links, function (a) {
var href = a.getAttribute('href') || '';
if (href === '/' || href.charAt(0) !== '/') return;
var hit = path.indexOf(href) === 0;
if (!hit && href === '/kakvo-izkupuvame/')
hit = /^\/(izkupuvane\/|izkupuvane-zhelyazo\/|izkupuvane-cvetni-metali\/)/.test(path);
if (!hit && href === '/en/what-we-buy/')
hit = /^\/en\/(ferrous-scrap|non-ferrous-scrap)\//.test(path);
if (hit) a.setAttribute('aria-current', 'page');
});
})();
const sections = document.querySelectorAll('section[id]');
const navLinks = document.querySelectorAll('.nav-links a');
const observer = new IntersectionObserver((entries) => {
entries.forEach(entry => {
if (entry.isIntersecting) {
navLinks.forEach(link => {
link.style.color = '';
link.style.fontWeight = '';
if (link.getAttribute('href') === '#' + entry.target.id) {
link.style.color = 'var(--green)';
link.style.fontWeight = '700';
}
});
}
});
}, { rootMargin: '-50% 0px -50% 0px' });
sections.forEach(s => observer.observe(s));
(function () {
if (!('IntersectionObserver' in window)) return;
document.documentElement.classList.add('js-reveal');
var sel = '.section-label,.section-label-dark,.section-title,.section-title-dark,.section-body,.section-body-dark,.service-card,.advantage,.step-card,.price-card,.client-logo,.faq-item,.feature-img,.about-img,.checklist,.prices-disclaimer';
var io = new IntersectionObserver(function (entries) {
entries.forEach(function (e) {
if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); }
});
}, { threshold: 0.12, rootMargin: '0px 0px -8% 0px' });
[].forEach.call(document.querySelectorAll(sel), function (el) {
el.classList.add('reveal');
var idx = [].indexOf.call(el.parentElement.children, el);
el.style.transitionDelay = (Math.min(idx, 6) * 60) + 'ms';
io.observe(el);
});
})();
(function () {
var nav = document.querySelector('.nav');
if (!nav) return;
var onScroll = function () { nav.classList.toggle('scrolled', window.scrollY > 12); };
onScroll();
window.addEventListener('scroll', onScroll, { passive: true });
})();
(function () {
var forms = document.querySelectorAll('form.qform');
if (!forms.length) return;
forms.forEach(function (f) {
f.addEventListener('submit', function (e) {
if (!f.action || f.action.indexOf('formspree') === -1) return; // друг action — нормален submit
e.preventDefault();
var btn = f.querySelector('button[type=submit]');
if (btn) {
btn.disabled = true; btn.dataset.t = btn.textContent;
btn.textContent = NA_ANGLIYSKI ? 'Sending…' : 'Изпращане…';
}
fetch(f.action, { method: 'POST', body: new FormData(f), headers: { 'Accept': 'application/json' } })
.then(function (r) {
if (r.ok) {
window.location.href = NA_ANGLIYSKI ? '/en/thank-you/' : '/blagodarim/';
}
else { throw new Error('bad'); }
})
.catch(function () {
if (btn) {
btn.disabled = false;
btn.textContent = btn.dataset.t || (NA_ANGLIYSKI ? 'Send request' : 'Изпрати заявка');
}
var n = f.querySelector('.form-note');
if (n) {
n.innerHTML = NA_ANGLIYSKI
? 'Something went wrong while sending. Please call <a href="tel:+359877775577" style="color:var(--green);font-weight:700;">+359 877 77 55 77</a> or write to progresstradesofia@gmail.com.'
: 'Възникна проблем при изпращането. Моля, обадете се на <a href="tel:+359877775577" style="color:var(--green);font-weight:700;">0877 77 55 77</a> или пишете на progresstradesofia@gmail.com.';
n.style.color = '#b00020';
}
});
});
});
})();
(function () {
var mm = document.getElementById('mobile-menu');
if (!mm) return;
function close() { setMenu(false); }
mm.querySelectorAll('a').forEach(function (a) { a.addEventListener('click', close); });
document.addEventListener('keydown', function (e) { if (e.key === 'Escape') close(); });
window.addEventListener('pageshow', function (e) {
if (e.persisted) { clearTimeout(mm._zatvaryane); mm.classList.remove('open', 'closing'); setMenu(false); }
});
var wide = window.matchMedia('(min-width:1025px)');
var onWide = function () { if (wide.matches) close(); };
if (wide.addEventListener) wide.addEventListener('change', onWide); else if (wide.addListener) wide.addListener(onWide);
})();
(function () {
var KEY = 'pt_poseshtenie';
var PROZOREC = 30 * 60 * 1000;         // 30 минути без активност
var CEL = 20000;                       // 20 секунди видимо време
var pamet = null;                      // резерва, ако хранилището е блокирано
function sesiya() {
var st = null;
try { st = JSON.parse(localStorage.getItem(KEY) || 'null'); } catch (e) {}
if (!st || typeof st !== 'object') st = pamet;
if (!st || typeof st !== 'object') st = {};
if (st.t && Date.now() - st.t > PROZOREC) st = {};   // изтекло — ново посещение
return st;
}
function zapishi(st) {
st.t = Date.now();
pamet = st;
try { localStorage.setItem(KEY, JSON.stringify(st)); } catch (e) {}
}
function vednaj(name) {
var st = sesiya();
if (st[name]) { zapishi(st); return false; }        // активен е — удължаваме
st[name] = 1; zapishi(st);
return true;
}
function push(name, params) {
(window.dataLayer = window.dataLayer || []).push(Object.assign({
event: name,
stranica: location.pathname,
ustroystvo: matchMedia('(pointer:coarse)').matches ? 'mobilen' : 'desktop'
}, params || {}));
}
function interest() {
if (vednaj('interest')) push('interest');
}
function contact(method) {
interest();                                          // контактът значи и интерес
if (vednaj('contact')) push('contact', { method: method });
}
document.addEventListener('click', function (e) {
var a = e.target.closest && e.target.closest('a[href]');
if (!a) return;
var href = a.getAttribute('href') || '';
if (href.indexOf('tel:') === 0) contact('phone');
else if (href.indexOf('mailto:') === 0) contact('email');
else if (href.indexOf('viber:') === 0) contact('viber');
else if (href.indexOf('maps.app.goo.gl') > -1 || href.indexOf('google.com/maps') > -1) contact('maps');
}, { passive: true, capture: true });
if (/^\/(zayavka|en\/request-a-quote)\/?$/.test(location.pathname) &&
document.referrer.indexOf(location.origin) === 0) contact('quote_form');
(function () {
if (sesiya().interest) return;
var posledno = Date.now();
document.addEventListener('visibilitychange', function () { posledno = Date.now(); });
var taymer = setInterval(function () {
var sega = Date.now(), delta = Math.min(sega - posledno, 2000);
posledno = sega;                                  // таймерът в скрит раздел
if (document.visibilityState !== 'visible') return;  // се забавя или спира,
if (sesiya().interest) { clearInterval(taymer); return; }  // затова има таван
var st = sesiya();
st.vidimo = (st.vidimo || 0) + delta;
zapishi(st);
if (st.vidimo >= CEL) { clearInterval(taymer); interest(); }
}, 1000);
})();
(function () {
var maks = 0, pusnat = false;
addEventListener('scroll', function () {
if (pusnat) return;              // иначе всяко ново дъно чете и пише в
var d = document.documentElement;   // хранилището насред самото скролване
var prevartaemo = d.scrollHeight - innerHeight;
if (prevartaemo < 400) return;
var y = window.scrollY || d.scrollTop || 0;
if (y <= maks) return;
maks = y;
if (y >= prevartaemo * 0.5 && y >= 600) { pusnat = true; interest(); }
}, { passive: true });
})();
(function () {
var st = sesiya();
if (!st.pati) st.pati = [];
if (st.pati.indexOf(location.pathname) < 0 && st.pati.length < 3)
st.pati.push(location.pathname);
zapishi(st);
if (st.pati.length >= 2) interest();
})();
if ((location.pathname.indexOf('/blagodarim') === 0 ||
location.pathname.indexOf('/en/thank-you') === 0) && vednaj('zayavka'))
push('zayavka_izpratena');
})();
(function () {
var OTPUSK_OT = '';                 // първи ден включително, напр. '2027-08-30'
var OTPUSK_DO = '';                 // последен ден включително; празно = изключено
var d;
try {
d = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Sofia' }));
} catch (e) { d = new Date(); }
function iso(x) {
return x.getFullYear() + '-' +
('0' + (x.getMonth() + 1)).slice(-2) + '-' + ('0' + x.getDate()).slice(-2);
}
var dnes = iso(d);
var vOtpusk = OTPUSK_OT && OTPUSK_DO && dnes >= OTPUSK_OT && dnes <= OTPUSK_DO;
var MESECI = ['януари','февруари','март','април','май','юни',
'юли','август','септември','октомври','ноември','декември'];
var MONTHS = ['January','February','March','April','May','June',
'July','August','September','October','November','December'];
function slovom(isoData) {            // '2027-08-30' → '30 август' / '30 August'
var ch = isoData.split('-');
var m = (+ch[1]) - 1;
return NA_ANGLIYSKI ? (+ch[2]) + ' ' + MONTHS[m] : (+ch[2]) + ' ' + MESECI[m];
}
if (vOtpusk) {
var bar = document.querySelector('[data-vacation]');
if (bar) {
var zagl = bar.querySelector('b');
if (zagl) zagl.textContent = NA_ANGLIYSKI
? 'Annual leave: ' + slovom(OTPUSK_OT) + ' – ' + slovom(OTPUSK_DO) + '.'
: 'Годишен отпуск: ' + slovom(OTPUSK_OT) + ' – ' + slovom(OTPUSK_DO) + '.';
bar.classList.add('on');
}
}
var notes = document.querySelectorAll('[data-closed-note]');
if (!notes.length) return;
var den = d.getDay(), chas = d.getHours() + d.getMinutes() / 60;
var otvoreno = !vOtpusk && den >= 1 && den <= 5 && chas >= 9 && chas < 17;
if (!otvoreno) {
if (vOtpusk) {
notes.forEach(function (n) {
var t = n.querySelector('span') || n;
t.textContent = NA_ANGLIYSKI
? 'We are on annual leave until ' + slovom(OTPUSK_DO) + '. Send a request or ' +
'message us on Viber — we reply as soon as we are back.'
: 'В годишен отпуск сме до ' + slovom(OTPUSK_DO) + '. Оставете ' +
'заявка или пишете на Viber — отговаряме веднага след това.';
});
}
notes.forEach(function (n) { n.classList.add('on'); });
}
})();
document.addEventListener('click', function (e) {
var a = e.target.closest && e.target.closest('a[data-yt]');
if (!a || a.classList.contains('is-playing')) return;
e.preventDefault();
var f = document.createElement('iframe');
f.src = 'https://www.youtube-nocookie.com/embed/' + a.getAttribute('data-yt') + '?autoplay=1&playsinline=1&rel=0';
f.title = a.getAttribute('aria-label') || 'Видео';
f.allow = 'autoplay; encrypted-media; picture-in-picture; fullscreen';
f.setAttribute('allowfullscreen', '');
a.classList.add('is-playing');
a.removeAttribute('href');
a.appendChild(f);
(window.dataLayer = window.dataLayer || []).push({ event: 'video_play', video: a.getAttribute('data-yt') });
});
(function () {
var root = document.querySelector('[data-tour]');
if (!root) return;
var slides = root.querySelectorAll('.tour-slide');
var tabs = root.querySelectorAll('.tour-tab');
var count = root.querySelector('.tour-count b');
var list = root.querySelector('.tour-list');
var n = slides.length, cur = 0, timer = null, MS = 6000;
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var visible = false, hover = false;
root.style.setProperty('--tour-ms', MS + 'ms');
root.classList.add('is-ready');
function show(i, fromUser) {
cur = (i + n) % n;
for (var k = 0; k < n; k++) {
var on = k === cur;
slides[k].classList.toggle('is-active', on);
tabs[k].classList.toggle('is-active', on);
tabs[k].setAttribute('aria-selected', on ? 'true' : 'false');
tabs[k].tabIndex = on ? 0 : -1;
if (on) { var img = slides[k].querySelector('img'); if (img) img.loading = 'eager'; }
}
var nx = slides[(cur + 1) % n].querySelector('img'); if (nx) nx.loading = 'eager';
if (count) count.textContent = (cur < 9 ? '0' : '') + (cur + 1);
var bar = tabs[cur].querySelector('.tour-bar');
if (bar) { bar.style.animation = 'none'; void bar.offsetWidth; bar.style.animation = ''; }
if (list && list.scrollWidth > list.clientWidth) {
var li = tabs[cur].parentNode;
list.scrollTo({ left: li.offsetLeft - list.offsetLeft, behavior: fromUser ? 'smooth' : 'auto' });
}
restart();
}
function stop() { clearTimeout(timer); timer = null; }
function restart() {
stop();
var run = visible && !hover && !reduce;
root.classList.toggle('is-paused', !run);
if (run) timer = setTimeout(function () { show(cur + 1); }, MS);
}
[].forEach.call(tabs, function (t, i) {
t.addEventListener('click', function () { show(i, true); });
t.addEventListener('keydown', function (e) {
var d = (e.key === 'ArrowRight' || e.key === 'ArrowDown') ? 1 : (e.key === 'ArrowLeft' || e.key === 'ArrowUp') ? -1 : 0;
if (d) { e.preventDefault(); show(cur + d, true); tabs[cur].focus(); }
});
});
[].forEach.call(root.querySelectorAll('.tour-arrow'), function (b) {
b.addEventListener('click', function () { show(cur + (+b.getAttribute('data-dir')), true); });
});
root.addEventListener('mouseenter', function () { hover = true; restart(); });
root.addEventListener('mouseleave', function () { hover = false; restart(); });
root.addEventListener('focusin', function () { hover = true; restart(); });
root.addEventListener('focusout', function () { hover = false; restart(); });
var stage = root.querySelector('.tour-stage'), x0 = null, y0 = null;
stage.addEventListener('touchstart', function (e) { x0 = e.touches[0].clientX; y0 = e.touches[0].clientY; }, { passive: true });
stage.addEventListener('touchend', function (e) {
if (x0 === null) return;
var dx = e.changedTouches[0].clientX - x0, dy = e.changedTouches[0].clientY - y0;
if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy)) show(cur + (dx < 0 ? 1 : -1), true);
x0 = null;
}, { passive: true });
if ('IntersectionObserver' in window) {
new IntersectionObserver(function (es) { visible = es[0].isIntersecting; restart(); }, { threshold: 0.35 }).observe(root);
} else { visible = true; }
show(0);
})();
